#!/usr/bin/env ruby
require 'json';require 'fileutils'
root=File.expand_path('..',__dir__);git=File.read(File.join(root,'.gitignore'));release=File.read(File.join(root,'.releaseignore'));required=%w[**/target/ **/build/ **/library/ **/temp/ **/node_modules/];checks={sourceIgnore:required.all?{|v|git.lines.map(&:strip).include?(v)},releaseIgnore:required.all?{|v|release.lines.map(&:strip).include?(v)},packageHallForbidden:JSON.parse(File.read(File.join(root,'config/release-allowlist.json')))['forbidden'].include?('server/Legacy*/target')};report={schemaVersion:1,requiredPatterns:required,checks:checks,passed:checks.values.all?};out=File.join(root,'docs/generated/pkg06-generated-policy.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort "PKG06 failed: #{checks}" unless report[:passed];puts 'PKG06 PASS: generated outputs excluded from source and release inputs'
